CREATE TABLE `assets` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(32) NOT NULL,
  `description` varchar(255) NOT NULL,
  `category` varchar(64) DEFAULT NULL,
  `location` varchar(128) DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `value` varchar(32) DEFAULT NULL,
  `hasChassi` tinyint(1) NOT NULL DEFAULT '0',
  `chassiNumber` varchar(64) DEFAULT NULL,
  `licensePlate` varchar(16) DEFAULT NULL,
  `patrimonialCode` varchar(16) DEFAULT NULL,
  `costCenterId` int DEFAULT NULL,
  `costCenterCode` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `assets_code_unique` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=1080001;
