/*!40000 ALTER TABLE `malotes` ENABLE KEYS */;
DROP TABLE IF EXISTS `purchaseRequests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `purchaseRequests` (
  `id` int NOT NULL AUTO_INCREMENT,
  `requestNumber` varchar(32) NOT NULL,
  `requesterId` int NOT NULL,
  `requesterName` varchar(128) NOT NULL,
  `department` varchar(128) NOT NULL,
  `costCenterId` int DEFAULT NULL,
  `costCenterCode` varchar(32) DEFAULT NULL,
  `application` varchar(255) NOT NULL,
  `urgencyLevel` enum('normal','urgente','emergencial') NOT NULL DEFAULT 'normal',
  `observations` text DEFAULT NULL,
  `totalEstimatedValue` decimal(14,2) DEFAULT NULL,
  `status` enum('rascunho','aguardando_gerente','aguardando_orcamento','aguardando_controladoria','aguardando_diretoria','aguardando_ordem_compra','aguardando_aprovacao_ceo','aguardando_aprovacao_compra','aguardando_comprovante_pagamento','aguardando_verificacao_compras','concluida','parcialmente_concluida','rejeitada','cancelada') NOT NULL DEFAULT 'aguardando_gerente',
  `budgetFileUrl` text DEFAULT NULL,
  `purchaseOrderNumber` varchar(64) DEFAULT NULL,
  `paymentMethod` enum('pix','boleto','cartao_avista','cartao_parcelado') DEFAULT NULL,
  `paymentInfo` text DEFAULT NULL,
  `deadlineAt` timestamp NULL DEFAULT NULL,
  `stepDeadlineAt` timestamp NULL DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `paymentProofUrl` longtext DEFAULT NULL,
  `paymentObservations` text DEFAULT NULL,
  `invoiceUrl` longtext DEFAULT NULL,
  `invoice2Url` text DEFAULT NULL,
  `isEnabledInMalotes` tinyint(1) NOT NULL DEFAULT '0',
  `cancellationDeadlineAt` timestamp NULL DEFAULT NULL,
  `cancellationWarningSentAt` timestamp NULL DEFAULT NULL,
  `ocSiagriUrl` text DEFAULT NULL,
  `orderValue` decimal(14,2) DEFAULT NULL,
  `orcamentoFeitoUrgente` tinyint(1) NOT NULL DEFAULT '0',
  `osMyfarm` varchar(64) DEFAULT NULL,
  `paymentInstallments` int DEFAULT NULL,
  `aiAnalysis` longtext DEFAULT NULL,
  `directorApprovals` text DEFAULT NULL COMMENT 'JSON array de aprovações parciais da Diretoria: [{userId, userName, approvedAt}]',
  `completedAt` timestamp NULL DEFAULT NULL,
  `farmId` int DEFAULT NULL,
  `farmName` varchar(128) DEFAULT NULL,
  `harvestId` int DEFAULT NULL,
  `harvestName` varchar(128) DEFAULT NULL,
  `maintenanceType` enum('preventiva','corretiva') DEFAULT NULL,
  `isPriority` tinyint(1) NOT NULL DEFAULT '0',
  `priorityOrder` int DEFAULT NULL,
  `prioritySetBy` varchar(128) DEFAULT NULL,
  `prioritySetAt` timestamp NULL DEFAULT NULL,
  `fuelType` enum('diesel','diesel_s10','alcool_gasolina_fazenda','alcool_gasolina_administrativo','lubrificantes') DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `purchaseRequests_requestNumber_unique` (`requestNumber`)
